import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Definizione di poligoni simili","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/f_geometria-del-piano-euclideo/fp/fpha.md","filePath":"lezioni/f_geometria-del-piano-euclideo/fp/fpha.md"}`),a={name:`lezioni/f_geometria-del-piano-euclideo/fp/fpha.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="definizione-di-poligoni-simili" tabindex="-1">Definizione di poligoni simili <a class="header-anchor" href="#definizione-di-poligoni-simili" aria-label="Permalink to “Definizione di poligoni simili”">​</a></h1><p><strong>Definizione:</strong><strong>Due poligoni sono simili se hanno tutti gli angoli uguali ed i lati corrispondenti in proporzione</strong></p><blockquote><p>Se il rapporto di similitudine vale <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn></mrow><annotation encoding="application/x-tex">1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span> allora i due poligoni, oltre che simili, sono anche congruenti.</p></blockquote><blockquote><p><strong>Nota:</strong> Secondo me migliore è la definizione: Se congiungendo i vertici corrispondenti di due poligoni tutte le congiungenti si intersecano in un unico punto allora i due poligoni sono simili.</p><p>Per la corrispondenza si preferisce parlare di [omotetia (fare link)]{.text-red}. Se i due poligoni sono congruenti allora il punto di intersezione è all&#39;infinito e le rette sono parallele.</p></blockquote><p>Siccome è piuttosto complicato considerare tutti i lati e gli angoli, anche qui si potrà parlare di criteri di similitudine, ma, operativamente, useremo un metodo più intuitivo:</p><p><strong>Due poligoni sono simili se è possibile suddividerli in triangoli ordinatamente simili</strong></p><p>Basta che consideri due vertici in corrispondenza e, da essi, tracci le congiungenti agli altri vertici: tutti i triangoli ottenuti sono tra loro simili.</p><blockquote><p>Puoi comunque considerare anche un punto interno al poligono ed il suo corrispondente nel secondo poligono e da questo tracciare tutte le congiungenti i vertici ed ottenere ancora triangoli simili: il problema è trovare due punti corrispondenti nei due poligoni: se usi la seconda definizione due punti si corrisponderanno nella similitudine se sono allineati con il centro dell&#39;omotetia (cioè il punto in cui si incrociano tutte le congiungenti i vertici).</p></blockquote>`,8)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};